-- One of each ingredient: the cleanup (after 20261008100000).
--
-- The shared ingredient list becomes 675 core ingredients and 23
-- family groups ("Syrup", "Citrus", "Bitters"), and every copy folds into the
-- one real row:
--   * names that only differ by accents, case or punctuation merge
--     ("Cachaca" and "Cachaça", "No. 3 Gin" and "No.3 Gin"). "Rosé" the wine
--     becomes "Rosé Wine", so it isn't folded into "Rose" the flower.
--   * 424 other names merge into their core ingredient and stay as
--     aliases ("1:1 Sugar Syrup", "Sugar Syrup", "Simple Syrup, 1:1" are all
--     Simple Syrup; "2:1 Sugar Syrup" and "Rich Syrup" are Rich Simple Syrup).
--   * 67 more rows that are the same thing under another name merge,
--     and plurals fold into the singular ("Lime Oils" into "Lime Oil").
--   * 5732 brands, forms and house versions say what they're a kind of
--     (Tanqueray -> London Dry Gin, Lavender Simple Syrup -> Simple Syrup,
--     Lime Juice -> Lime). A different recipe stays its own row: Rich Simple
--     Syrup (2:1) is a kind of Simple Syrup (1:1), not a copy of it.
--   * the house basics get their one recipe, in grams, if they had none:
--     Simple Syrup 1:1, Rich Simple Syrup 2:1, Demerara and Rich Demerara,
--     Honey and Rich Honey Syrup, Saline Solution 20%.
--
-- The lists were drawn up from every shared ingredient name in production
-- (2026-10-07) by hand-checked classification; scratch notes aren't in the
-- repo. Everything is matched by name key, so rows that don't exist here are
-- skipped, and running it twice changes nothing more. Venue ingredients
-- aren't touched: their names are private. Merging moves every reference
-- (spec lines, categories, images, costs) with private.merge_ingredient().
-- Moving spec lines would queue flavour jobs and sketches; the queue is put
-- back as it was and the image worker flag stops new sketches.

SET "app.image_worker" = 'on';
SET "app.ingredient_merge" = 'on';

-- No paid flavour jobs: merging a name into its synonym doesn't change how a
-- drink tastes, and with CATALOG_AI_FILL=on each queued job is a paid AI fill
-- (same rule as 20261008000000_cocktail_omakase). Note the queue now and put
-- it back at the end.
CREATE TEMP TABLE "flavor_jobs_before" AS SELECT * FROM "private"."item_flavor_jobs";

CREATE TEMP TABLE "core_in" ("name" "text" PRIMARY KEY, "kind_of" "text", "family" boolean NOT NULL, "id" "uuid");
CREATE TEMP TABLE "alias_in" ("alias" "text" NOT NULL, "core" "text" NOT NULL);
CREATE TEMP TABLE "merge_in" ("from_name" "text" NOT NULL, "into_name" "text" NOT NULL);
CREATE TEMP TABLE "link_in" ("name" "text" NOT NULL, "target" "text" NOT NULL);
CREATE TEMP TABLE "plural_in" ("from_name" "text" NOT NULL, "into_name" "text" NOT NULL);
CREATE TEMP TABLE "recipe_in" ("core" "text" NOT NULL, "position" integer NOT NULL, "ingredient" "text" NOT NULL, "grams" numeric NOT NULL);

