-- ---------------------------------------------------------------------------
-- Every shared ingredient by key, kept current as rows merge
-- ---------------------------------------------------------------------------

CREATE TEMP TABLE "shared_ing" AS
SELECT i.id, i.name, public.ingredient_key(i.name) AS key, i.brand_maker, i.created_at,
       (SELECT count(*) FROM public.recipes r WHERE r.ingredient_item_id = i.id OR r.parent_ingredient_id = i.id) AS uses
  FROM public.items i
 WHERE i.item_type = 'ingredient' AND i.bar_id IS NULL;
CREATE INDEX ON "shared_ing" ("key");

DO $$
DECLARE
    r record;
    v_keep uuid;
    v_id uuid;
BEGIN
    -- Rosé the wine isn't Rose the flower: give the wine its full name.
    FOR r IN SELECT s.id FROM shared_ing s
              WHERE s.name = 'Rosé' AND EXISTS (SELECT 1 FROM shared_ing o WHERE o.key = 'rose' AND o.id <> s.id) LOOP
        SELECT id INTO v_keep FROM shared_ing WHERE key = 'rose wine' LIMIT 1;
        IF v_keep IS NULL THEN
            UPDATE public.items SET name = 'Rosé Wine' WHERE id = r.id;
            UPDATE shared_ing SET name = 'Rosé Wine', key = 'rose wine' WHERE id = r.id;
        ELSE
            PERFORM private.merge_ingredient(r.id, v_keep);
            DELETE FROM shared_ing WHERE id = r.id;
        END IF;
    END LOOP;

    -- One row per key: keep the core spelling, else the most used, else the oldest.
    FOR r IN SELECT key FROM shared_ing GROUP BY key HAVING count(*) > 1 LOOP
        SELECT s.id INTO v_keep FROM shared_ing s LEFT JOIN core_in c ON c.name = s.name
         WHERE s.key = r.key ORDER BY (c.name IS NOT NULL) DESC, s.uses DESC, s.created_at, s.id LIMIT 1;
        FOR v_id IN SELECT id FROM shared_ing WHERE key = r.key AND id <> v_keep LOOP
            PERFORM private.merge_ingredient(v_id, v_keep);
            DELETE FROM shared_ing WHERE id = v_id;
        END LOOP;
    END LOOP;

    -- Every core ingredient and family exists once, spelled the core way. One
    -- that only exists under another name takes over that row (keeping its
    -- pictures and history) rather than starting a new one.
    FOR r IN SELECT name FROM core_in LOOP
        SELECT id INTO v_id FROM shared_ing WHERE key = public.ingredient_key(r.name);
        IF v_id IS NULL THEN
            SELECT s.id INTO v_id FROM alias_in a JOIN shared_ing s ON s.key = public.ingredient_key(a.alias)
             WHERE a.core = r.name AND s.brand_maker IS NULL AND s.id NOT IN (SELECT id FROM core_in WHERE id IS NOT NULL)
             ORDER BY s.uses DESC, s.created_at LIMIT 1;
        END IF;
        IF v_id IS NULL THEN
            INSERT INTO public.items (name, item_type) VALUES (r.name, 'ingredient') RETURNING id INTO v_id;
            INSERT INTO shared_ing (id, name, key, created_at, uses) VALUES (v_id, r.name, public.ingredient_key(r.name), now(), 0);
        ELSE
            UPDATE public.items SET name = r.name WHERE id = v_id AND name IS DISTINCT FROM r.name;
            UPDATE shared_ing SET name = r.name, key = public.ingredient_key(r.name) WHERE id = v_id;
        END IF;
        UPDATE core_in SET id = v_id WHERE name = r.name;
    END LOOP;

    -- Other names fold into their core ingredient. A named bottle never
    -- merges (it becomes a kind of it below), and one core row never folds
    -- into another.
    FOR r IN
        SELECT s.id AS from_id, c.id AS into_id, s.brand_maker
          FROM alias_in a JOIN core_in c ON c.name = a.core JOIN shared_ing s ON s.key = public.ingredient_key(a.alias)
        UNION
        SELECT s.id, c.id, s.brand_maker
          FROM merge_in m JOIN core_in c ON c.name = m.into_name JOIN shared_ing s ON s.key = public.ingredient_key(m.from_name)
    LOOP
        CONTINUE WHEN r.from_id = r.into_id OR r.brand_maker IS NOT NULL;
        CONTINUE WHEN EXISTS (SELECT 1 FROM core_in WHERE id = r.from_id);
        CONTINUE WHEN NOT EXISTS (SELECT 1 FROM shared_ing WHERE id = r.from_id);
        PERFORM private.merge_ingredient(r.from_id, r.into_id);
        DELETE FROM shared_ing WHERE id = r.from_id;
    END LOOP;

    -- Plurals fold into the singular, wherever that row is.
    FOR r IN
        SELECT f.id AS from_id, t.id AS into_id
          FROM plural_in p
          JOIN shared_ing f ON f.key = public.ingredient_key(p.from_name)
          JOIN shared_ing t ON t.key = public.ingredient_key(p.into_name)
         WHERE f.id <> t.id AND f.brand_maker IS NULL
    LOOP
        CONTINUE WHEN EXISTS (SELECT 1 FROM core_in WHERE id = r.from_id);
        CONTINUE WHEN NOT EXISTS (SELECT 1 FROM shared_ing WHERE id = r.from_id) OR NOT EXISTS (SELECT 1 FROM shared_ing WHERE id = r.into_id);
        PERFORM private.merge_ingredient(r.from_id, r.into_id);
        DELETE FROM shared_ing WHERE id = r.from_id;
    END LOOP;
END;
$$;

-- ---------------------------------------------------------------------------
-- The core list and its tree
-- ---------------------------------------------------------------------------

UPDATE public.items i SET is_core = NOT c.family, hide_from_search = false
  FROM core_in c WHERE i.id = c.id;

UPDATE public.items i
   SET generic_id = (SELECT p.id FROM core_in c JOIN core_in p ON p.name = c.kind_of WHERE c.id = i.id)
 WHERE i.id IN (SELECT id FROM core_in);

-- Brands, forms and house versions: a kind of their core ingredient.
UPDATE public.items i SET generic_id = c.id
  FROM link_in l
  JOIN core_in c ON c.name = l.target
  JOIN shared_ing s ON s.key = public.ingredient_key(l.name)
 WHERE i.id = s.id AND i.id <> c.id AND i.generic_id IS DISTINCT FROM c.id
   AND NOT EXISTS (SELECT 1 FROM core_in x WHERE x.id = i.id);
-- Merges skipped for named bottles: those are kinds of it too.
UPDATE public.items i SET generic_id = c.id
  FROM (SELECT a.alias AS name, a.core AS target FROM alias_in a UNION SELECT from_name, into_name FROM merge_in) m
  JOIN core_in c ON c.name = m.target
  JOIN shared_ing s ON s.key = public.ingredient_key(m.name)
 WHERE i.id = s.id AND i.id <> c.id AND s.brand_maker IS NOT NULL AND i.generic_id IS NULL;

-- No loops ("A is a kind of B is a kind of A"): drop a non-core link in each.
DO $$
DECLARE
    v_id uuid;
BEGIN
    LOOP
        WITH RECURSIVE walk(start, cur, depth, path) AS (
            SELECT id, generic_id, 1, ARRAY[id] FROM public.items WHERE item_type = 'ingredient' AND generic_id IS NOT NULL
            UNION ALL
            SELECT w.start, i.generic_id, w.depth + 1, w.path || i.id
              FROM walk w JOIN public.items i ON i.id = w.cur
             WHERE i.generic_id IS NOT NULL AND NOT i.id = ANY (w.path[2:]) AND w.depth < 12
        )
        SELECT w.start INTO v_id FROM walk w JOIN public.items i ON i.id = w.start
         WHERE w.cur = w.start ORDER BY i.is_core, w.start LIMIT 1;
        EXIT WHEN v_id IS NULL;
        UPDATE public.items SET generic_id = NULL WHERE id = v_id;
    END LOOP;
END;
$$;

-- Typing another name finds the core ingredient.
INSERT INTO public.ingredient_aliases (key, item_id)
SELECT DISTINCT ON (x.k) x.k, c.id
  FROM (SELECT public.ingredient_key(a.alias) AS k, a.core FROM alias_in a) x
  JOIN core_in c ON c.name = x.core
 WHERE x.k IS NOT NULL AND NOT EXISTS (SELECT 1 FROM shared_ing s WHERE s.key = x.k)
 ORDER BY x.k
ON CONFLICT (key) DO NOTHING;

-- The one recipe for the house basics, when they have none yet.
INSERT INTO public.recipes (recipe_item_id, ingredient_item_id, amount, unit, sort_order)
SELECT c.id, s.id, r.grams, 'g', r.position
  FROM recipe_in r
  JOIN core_in c ON c.name = r.core
  JOIN shared_ing s ON s.key = public.ingredient_key(r.ingredient)
 WHERE NOT EXISTS (SELECT 1 FROM public.recipes x WHERE x.recipe_item_id = c.id);

-- --- Put the flavour job queue back ---
DELETE FROM "private"."item_flavor_jobs" j
WHERE NOT EXISTS (SELECT 1 FROM "flavor_jobs_before" o WHERE o.item_id = j.item_id);
UPDATE "private"."item_flavor_jobs" j SET
    "status" = o.status, "revision" = o.revision, "attempts" = o.attempts, "run_after" = o.run_after,
    "lease_until" = o.lease_until, "last_error" = o.last_error, "updated_at" = o.updated_at
FROM "flavor_jobs_before" o
WHERE j.item_id = o.item_id AND j.revision <> o.revision;
DROP TABLE "flavor_jobs_before";

DROP TABLE "core_in", "alias_in", "merge_in", "link_in", "plural_in", "recipe_in", "shared_ing";
RESET "app.ingredient_merge";
RESET "app.image_worker";
